/// Binary search the sorted namespace. Note: a hit is NOT existence —
/// the literal `missingno` and the armor-trim family are pinned missing.
pub fn texture_index(id: &str) -> Option<u16> {
    TEXTURE_IDS.binary_search(&id).ok().map(|i| i as u16)
}

/// The id's RGBA8 texels (empty for a missing material).
pub fn texture_rgba(idx: u16) -> &'static [u8] {
    let i = idx as usize;
    &TEXELS[OFFSETS[i] as usize..OFFSETS[i + 1] as usize]
}

/// The id's pixel dims (0, 0) for a missing material.
pub fn texture_size(idx: u16) -> (u16, u16) {
    (WIDTHS[idx as usize], HEIGHTS[idx as usize])
}

/// True when the id has no PNG in the jar (the vanilla checkerboard).
pub fn is_missing(idx: u16) -> bool {
    WIDTHS[idx as usize] == 0
}

pub fn has_textures() -> bool { N_TEXTURES > 0 }
